public(package) fun handle_liquidation<MarketType, DebtType, CollateralType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    available_repay_coin: Coin<DebtType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>, u64) {
    let MarketConfiguration { close_factor, close_factor_bypass_min_value } = *self.market_config();

    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());

    let emode_group_id = obligation.emode_group();
    let collateral_name = type_name::with_defining_ids<CollateralType>();

    let emode_group = self.emode_group_registry.borrow_emode_group_mut(emode_group_id);
    let collateral_setting = emode_group.borrow_emode(collateral_name).collateral();
    // cannot liquidate asset that is not collateral
    assert!(collateral_setting.can_be_collateral(), error::asset_not_collateral());

    let asset = self.assets.load_mut_by_type(collateral_name);
    assert!(!asset.liquidation_paused(), error::liquidation_paused_for_asset());

    let liquidation_params = LiquidationParams {
        liquidation_ltv_threshold_override: std::option::none(),
        liquidation_incentive: collateral_setting.liquidation_incentive(),
        liquidation_revenue_factor: self.assets.load_by_type(type_name::with_defining_ids<CollateralType>()).asset_config().liquidation_fee_rate(),
        close_factor,
        close_factor_bypass_min_value,
    };

    liquidation_inner<MarketType, DebtType, CollateralType>(
        &mut self.id,
        &self.assets,
        emode_group,
        &mut self.reserves,
        obligation,
        &liquidation_params,
        available_repay_coin,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    )
}

public(package) fun handle_debt_auto_deleverage<MarketType, DebtType, CollateralType>(
    self: &mut Market<MarketType>,
    obligation_id: ID,
    available_repay_coin: Coin<DebtType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
    now: u64,
    ctx: &mut TxContext,
): (Coin<CollateralType>, Coin<DebtType>, u64) {
    let close_factor_bypass_min_value = self.market_config().close_factor_bypass_min_value;

    let debt_type = type_name::with_defining_ids<DebtType>();
    let collateral_type = type_name::with_defining_ids<CollateralType>();

    let obligation = self.obligations.borrow_mut(obligation_id);
    assert!(obligation.market_id() == self.id.uid_as_inner(), error::obligation_from_different_market());

    let emode_group_id = obligation.emode_group();
    let emode_group = self.emode_group_registry.borrow_emode_group_mut(obligation.emode_group());

    let collateral_setting = emode_group.borrow_emode(collateral_type).collateral();
    // cannot liquidate asset that is not collateral
    assert!(collateral_setting.can_be_collateral(), error::asset_not_collateral());

    let max_liquidation_incentive = collateral_setting.liquidation_incentive();


    let adl_registry = dynamic_field::borrow<ADLRegistryKey, AutoDeleverageRegistry>(&self.id, ADLRegistryKey {});
    let timelock = *adl_registry.get_borrow_deleverage(debt_type, emode_group_id);

    let asset = self.assets.load_mut_by_type(debt_type);
    accrue_interest<MarketType>(debt_type, &mut self.reserves, asset.asset_config(), asset.interest_model(), now);

    let total_debt = (*self.reserves.load_by_type(debt_type).debt()).floor();
    let debt_params = timelock.inner();
    debt_params.ensure_limit_breached(total_debt);


    let activation_time = timelock.get_secs_since_activation(clock);
    let liquidation_params = LiquidationParams {
        liquidation_ltv_threshold_override: std::option::some(debt_params.liquidation_ltv(activation_time)),
        // adl liquidation_incentive should not have exceeded non-adl liquidation_incentive
        liquidation_incentive: debt_params.liquidation_incentive(activation_time).min(max_liquidation_incentive),
        liquidation_revenue_factor: float::zero(),
        close_factor: debt_params.close_factor(),
        close_factor_bypass_min_value,
    };

/// @title Module for flash loan from base asset pools
module protocol::flash_loan;

use std::type_name::{Self, TypeName};
use std::string::String;

use sui::coin::Coin;
use sui::clock::Clock;

use sui::event::emit;

use x_oracle::x_oracle::XOracle;
use x_oracle::user_oracle::get_price;

use protocol::app::{ProtocolApp, PackageCallerCap};
use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::{Market, FlashLoan};
use protocol::value::coin_value;

public struct BorrowFlashLoanEvent has copy, drop {
    market: TypeName,
    borrower: address,
    asset: TypeName,
    amount: u64,
    fee: u64,
}

public struct RepayFlashLoanEvent has copy, drop {
    market: TypeName,
    borrower: address,
    asset: TypeName,
    amount: u64,
    fee: u64,
}

public fun borrow_flash_loan<MarketType, CoinType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    market: &mut Market<MarketType>,

    emode_group: u8,
    amount: u64,

    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    app.ensure_has_permission(object::id(cap), protocol::whitelist_admin::flash_loan());

    borrow_flash_loan_inner<MarketType, CoinType>(market, amount, emode_group, ctx)
}

/// @notice Repay flash loan to market
/// @dev This is the only method to repay flash loan, consume the flash loan hot potato object
/// @param version The version control object, contract version must match with this
/// @param market The market object, it contains base assets, and related protocol configs
/// @param coin The coin object to repay
/// @param loan The flash loan hot potato object, which contains the borrowed amount and fee
/// @ctx The SUI transaction context object
/// @custom:T The type of asset to repay
public fun repay_flash_loan<MarketType, CoinType>(
    app: &mut ProtocolApp,
    market: &mut Market<MarketType>,

    coin: Coin<CoinType>,
    loan: FlashLoan<MarketType, CoinType>,

    ctx: &mut TxContext,
) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    // Emit the repay flash loan event
    emit(RepayFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        // amount is total repay coin amount
        amount: coin.value(),
        fee: loan.fee(),
    });

    let referral = app.referral_mut();
    // Put the asset back to the market and consume the flash loan hot potato object
    market.repay_flash_loan(coin, loan, referral, std::option::none(), ctx);
}

public fun repay_flash_loan_increase_referral_qualification<MarketType, CoinType>(
    app: &mut ProtocolApp,
    market: &mut Market<MarketType>,

    coin: Coin<CoinType>,
    loan: FlashLoan<MarketType, CoinType>,

    maybe_referral_code: Option<String>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,

    ctx: &mut TxContext,
) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    // Emit the repay flash loan event
    emit(RepayFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        // amount is total repay coin amount
        amount: coin.value(),
        fee: loan.fee(),
    });

    let referral = app.referral_mut();
    track_referral(referral, ctx.sender(), loan.loan_amount(), type_name::with_defining_ids<CoinType>(), coin_decimals_registry, x_oracle, clock);
    let maybe_referral_code = referral.try_map_referral_code(ctx.sender(), maybe_referral_code);

    // Put the asset back to the market and consume the flash loan hot potato object
    market.repay_flash_loan(coin, loan, referral, maybe_referral_code, ctx);
}

fun borrow_flash_loan_inner<MarketType, CoinType>(
    market: &mut Market<MarketType>,
    amount: u64,
    emode_group: u8,
    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let (coin, flash_loan) = market.borrow_flash_loan(emode_group, amount, ctx);

    // Emit the borrow flash loan event
    emit(BorrowFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        fee: flash_loan.fee(),
        amount,
    });

    // Return the borrowed coin object and the flash loan hot potato object
    (coin, flash_loan)
}

fun track_referral(
    referral: &mut protocol::referral::Referral,

    who: address,

    token_amount: u64,
    token_type: TypeName,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
) {
    if (referral.is_qualified_to_create_referral_code(who)) return;

    let decimals = coin_decimals_registry.decimals(token_type);
    // always use usd price
    let usd_price = get_price(x_oracle, token_type, x_oracle::x_oracle::usd(), clock);
    let collateral_value_usd = coin_value(usd_price, math::float::from(token_amount), decimals);

    referral.increase_usd_qualification(who, collateral_value_usd.floor());
}

